{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, which shares the same benzoquinolizine core and 9,10-dimethoxy substitution as the query, has a very low mean oral systemic availability of 0.049 ± 0.032 in patients, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a prodrug of a tetrabenazine metabolite with the same core, has an absolute oral bioavailability of approximately 49% in humans, indicating that core modifications can raise F above 20%, but the query lacks the prodrug ester moiety.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C62"],
      "claim": "Almorexant, which contains a dimethoxytetrahydroisoquinoline motif, has an absolute oral bioavailability of about 11% in humans, supporting low F for the query's tetrahydroisoquinoline-related scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Noscapine, a tetrahydroisoquinoline alkaloid, has an absolute oral bioavailability of about 30% in humans, with a wide range of 16–58%, providing weak and uncertain support for F above 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "Verapamil, which shares the dimethoxyphenethylamine and tertiary amine features, has an absolute oral bioavailability of about 20–24% in humans, which is borderline relative to the 20% threshold and does not affirmatively support high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's benzoquinolizine core is most closely related to tetrabenazine, which has very low absolute oral bioavailability (~5%) in humans. Although some analogs with the tetrahydroisoquinoline motif (valbenazine, noscapine) show F above 20%, the query is not a prodrug and retains the metabolically labile core. The weight of direct, transferable human evidence supports F < 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule itself.",
    "The impact of the N-alkyl side chain terminating in a dimethoxytetrahydroisoquinoline on metabolic stability and absorption is unknown.",
    "The relative contribution of first-pass metabolism versus poor absorption to the low F of the core scaffold is not fully resolved."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C38"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tetrabenazine"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C29"],
      "decision_effect": "weakened",
